package org.sleepwell.app;
import android.content.*;import android.net.Uri;import android.os.*;import java.io.*;import java.lang.ref.WeakReference;import java.util.concurrent.*;import java.util.concurrent.atomic.AtomicReference;
/** Retained in-memory draft and explicit document writer. Never saves payload to app preferences/files. */
final class GeneratedMorningQrJob {
 enum Phase{PREPARING,READY,CHOOSING,WRITING,PRINTING,ERROR}
 static final class State{final Phase phase;final GeneratedMorningQr.Document document;final String message;State(Phase phase,GeneratedMorningQr.Document document,String message){this.phase=phase;this.document=document;this.message=message;}boolean busy(){return phase==Phase.PREPARING||phase==Phase.CHOOSING||phase==Phase.WRITING||phase==Phase.PRINTING;}}
 interface Observer{void changed(State state);}final String payload;private final Context app;private final Handler main=new Handler(Looper.getMainLooper());private final ExecutorService worker=Executors.newSingleThreadExecutor();private WeakReference<Observer> observer=new WeakReference<>(null);private volatile boolean closed,cancelled;private int version;private State state;private String choice="";private final AtomicReference<ParcelFileDescriptor> descriptor=new AtomicReference<>();private final AtomicReference<CancellationSignal> cancellation=new AtomicReference<>();
 GeneratedMorningQrJob(Context app,String payload,String label,boolean restored){this.app=app.getApplicationContext();this.payload=GeneratedMorningQr.validate(payload);prepare(label,restored?"Unfinished code restored. Review it and choose a new export destination; no export was replayed.":"");}
 State state(){return state;}void observe(Observer target){observer=new WeakReference<>(target);target.changed(state);}void detach(Observer target){if(observer.get()==target)observer.clear();}private void publish(State next){if(closed)return;state=next;Observer target=observer.get();if(target!=null)target.changed(next);}
 void prepare(String label){if(!closed&&!state.busy())prepare(label,"");}
 private void prepare(String label,String message){String clean=MorningCode.label(label);int ticket=++version;publish(new State(Phase.PREPARING,null,"Preparing a new local printable code…"));worker.execute(()->{try{GeneratedMorningQr.Document document=GeneratedMorningQr.render(payload,clean);main.post(()->{if(ticket==version)publish(new State(Phase.READY,document,message));});}catch(Exception failure){main.post(()->{if(ticket==version)publish(new State(Phase.ERROR,null,"The printable code could not be prepared. Try again."));});}});}
 boolean choose(String format){if(closed||state.phase!=Phase.READY||state.document==null||!format.equals("png")&&!format.equals("pdf"))return false;choice=format;publish(new State(Phase.CHOOSING,state.document,"Choose a new "+format.toUpperCase(java.util.Locale.ROOT)+" destination."));return true;}
 void cancelChoice(){if(state.phase==Phase.CHOOSING){choice="";publish(new State(Phase.READY,state.document,"Export cancelled. Enrollment has not changed."));}}
 void write(Uri uri,String format){if(closed||state.phase!=Phase.CHOOSING||!choice.equals(format))return;choice="";if(uri==null||!"content".equals(uri.getScheme())){publish(new State(Phase.READY,state.document,"Choose a document destination in Android Files."));return;}GeneratedMorningQr.Document document=state.document;byte[] bytes=format.equals("png")?document.png:document.pdf;cancelled=false;publish(new State(Phase.WRITING,document,"Saving the printable code…"));worker.execute(()->{String message;try{check();CancellationSignal signal=new CancellationSignal();cancellation.set(signal);try{ParcelFileDescriptor file=app.getContentResolver().openFileDescriptor(uri,"wt",signal);if(file==null)throw new IOException("Destination unavailable");descriptor.set(file);try(OutputStream output=new ParcelFileDescriptor.AutoCloseOutputStream(file)){for(int at=0;at<bytes.length;at+=8192){check();output.write(bytes,at,Math.min(8192,bytes.length-at));}output.flush();}finally{descriptor.compareAndSet(file,null);}}finally{cancellation.compareAndSet(signal,null);}check();message=format.toUpperCase(java.util.Locale.ROOT)+" saved and closed. Tap Use generated code, then Save code and Save alarm to enroll it.";}catch(Exception failure){message=cancelled?"Export cancelled. A partial destination may remain; remove it before retrying.":"Export failed. A partial destination may remain; remove it before retrying. Enrollment has not changed.";}String text=message;main.post(()->publish(new State(Phase.READY,document,text)));});}
 boolean beginPrint(){if(closed||state.phase!=Phase.READY||state.document==null)return false;publish(new State(Phase.PRINTING,state.document,"Android manages print preview and printer selection. Enrollment has not changed."));return true;}
 void finishPrint(){if(!closed&&state.phase==Phase.PRINTING)publish(new State(Phase.READY,state.document,"Print preview closed. Android manages print status. Save enrollment separately."));}
 void writePrint(ParcelFileDescriptor destination,CancellationSignal signal,android.print.PrintDocumentAdapter.WriteResultCallback callback,android.print.PrintAttributes attributes){if(closed){try{destination.close();}catch(IOException ignored){}callback.onWriteCancelled();return;}GeneratedMorningQr.Document document=state.document;worker.execute(()->{try(OutputStream output=new ParcelFileDescriptor.AutoCloseOutputStream(destination)){if(document==null)throw new IOException("Code document unavailable");byte[] bytes=GeneratedMorningQr.printPdf(app,document.preview,attributes);for(int at=0;at<bytes.length;at+=8192){if(closed||signal.isCanceled())throw new InterruptedIOException();output.write(bytes,at,Math.min(8192,bytes.length-at));}output.flush();}catch(Exception error){main.post(()->{if(signal.isCanceled()||closed)callback.onWriteCancelled();else callback.onWriteFailed("Printable code could not be delivered.");});return;}main.post(()->{if(signal.isCanceled()||closed)callback.onWriteCancelled();else callback.onWriteFinished(new android.print.PageRange[]{android.print.PageRange.ALL_PAGES});});});}
 void cancelWrite(){if(state.phase!=Phase.WRITING||cancelled)return;cancelled=true;cancelNative();}
 private void check()throws InterruptedIOException{if(closed||cancelled)throw new InterruptedIOException();}
 private void cancelNative(){ParcelFileDescriptor file=descriptor.get();CancellationSignal signal=cancellation.get();if(file==null&&signal==null)return;Thread thread=new Thread(()->{try{if(signal!=null)signal.cancel();}catch(RuntimeException ignored){}finally{if(file!=null)try{file.close();}catch(IOException ignored){}}},"SleepWell-code-export-cancel");thread.setDaemon(true);thread.start();}
 void close(){if(closed)return;closed=true;cancelled=true;version++;observer.clear();cancelNative();worker.shutdown();}
}
